    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR binding to port");
        exit(1);
    }

    // Send welcome message
    char msg[BUFFER_SIZE];
    snprintf(msg, sizeof(msg), "CONNECT OK %d", VERSION);
    sendto(sockfd, msg, strlen(msg), 0, (struct sockaddr*)&cli_addr, sizeof(cli_addr));

    while (1) {
        int n = recvfrom(sockfd, packet, sizeof(packet), 0, (struct sockaddr*)&cli_addr, &cli_len);
        if (n < 0 || n != (int)sizeof(controller_state)) {
            continue;
        }

        if ((char*)packet[0] != 'P' || memchr(packet, 'E', 1) != packet + 0) {
            printf("Invalid packet header received\n");
            break;
        }
    }

    close(sockfd);
}

struct controller_state {
