```zig
const std = @import("std");
const rl = @import("raylib");
const net = std.net;
const posix = std.posix;

// Enum defines input controls
const ControllerEvents = enum(i16) {
    ANALOG_LX = 0,
    ANALOG_LY = 1,
    ANALOG_RX = 2,
    ANALOG_RY = 3,
    L1 = 4,
    L2 = 5,
    R1 = 6,
    R2 = 7,
    TRIANGLE = 8,
    CROSS = 9,
    SQUARE = 10,
    CIRCLE = 11,
    UP = 12,
    DOWN = 13,
    LEFT = 14,
    RIGHT = 15,
    SELECT = 16,
    START = 17,
};

pub fn main() anyerror!void {
    const alloc = std.heap.page_allocator;
    _ = alloc;

    rl.initWindow(800, 450, "Raylib-Zig - Keyboard to Controller Input");
    defer rl.closeWindow();

    rl.setTargetFPS(60);

    var controllerState = [_]i16{
        0x0, 0x0, 0x0, 0x0, 0x1, 0x0, 0x1, 0x0,
        0x1, 0x0, 0x1, 0x0, 0x1, 0x0, 0x1, 0x0, 0x1, 0x0, 0x1,
    };

    var sendBuf = [256]u8{0};
    var addr = try net.Address.parseIp4("127.0.0.1", 31415);

    var sock = try posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);
    defer posix.close(sock);

    while (!rl.windowShouldClose()) {
        // Map keys to controller state
        controllerState[@intFromEnum(ControllerEvents.UP)] = if (rl.isKeyDown(rl.KeyboardKey.key_up)) 1 else 0;
        controllerState[@intFromEnum(ControllerEvents.DOWN)] = if (rl.isKeyDown(rl.KeyboardKey.key_down)) 1 else 0;
        controllerState[@intFromEnum(ControllerEvents.LEFT)] = if (rl.isKeyDown(rl.KeyboardKey.key_left)) 1 else 0;
        controllerState[@intFromEnum(ControllerEvents.RIGHT)] = if (rl.isKeyDown(rl.KeyboardKey.key_right)) 1 else 0;

        // Pack control data: version + 18 i16 values
        var len = 0;
        sendBuf[len] = VERSION_VALUE;
        for (controllerState, 0..) |val, idx| {
            len += @intCast(@bitCast(@as(u8, val)));
            sendBuf[idx + 1] = val;
        }

        const packet = sendBuf[0..len];
        sendto(sock, packet, len, 0, &addr.any, addr.getOsSockLen());

        rl.beginDrawing();
        rl.clearBackground(rl.Color.white);
        rl.drawText("Arrow Keys → Virtual Controller", 190, 200, 20, rl.Color.light_gray);
        rl.endDrawing();
    }
}
```

### 📄 Additional Notes:
- Ensure `VERSION_VALUE`, `sendPacket()` etc. are defined in Zig module or imported.
- Use byte-order awareness (`htons()`, etc.) to avoid mismatches when sending packets.
- Consider adding a handshake mechanism (ACK/NAK) if latency becomes an issue over long-term usage.

By adopting this unified protocol, both the server and client now reliably share control state in a precise, extensible binary format suitable for gamepad emulation over UDP.

