```zig
fn writeI16BE(out: []u8, value: i16) void {
    const bits: u16 = @bitCast(value);
    out[0] = @truncate(bits >> 8);
    out[1] = @truncate(bits);
}

const EVENT_COUNT = 18;

var packet: [EVENT_COUNT * 4]u8 = undefined;
for (controllerState, 0..) |value, i| {
    const offset = i * 4;
    writeI16BE(packet[offset..][0..2], @intCast(i));
    writeI16BE(packet[offset + 2..][0..2], value);
}

const addr = try net.Address.parseIp4("127.0.0.1", 31415);
_ = try posix.sendto(sock, &packet, 0, &addr.any, addr.getOsSockLen());
```

