import React, { useEffect, useState } from 'react';
import { Pressable, Text, View } from 'react-native';

export default function ExpandableText({
  text,
  textStyle,
  seeMoreStyle,
  containerStyle,
  seeMoreLabel = 'See more',
}) {
  const [width, setWidth] = useState(0);
  const [lineCount, setLineCount] = useState(null);
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    setLineCount(null);
    setExpanded(false);
  }, [text, width]);

  const onTextLayout = (event) => {
    setLineCount(event.nativeEvent.lines.length);
  };

  const isOverflowing = lineCount != null && lineCount > 1;

  return (
    <View
      style={containerStyle}
      onLayout={(event) => setWidth(event.nativeEvent.layout.width)}
    >
      {width > 0 && lineCount == null && (
        <Text
          accessible={false}
          onTextLayout={onTextLayout}
          style={[textStyle, { position: 'absolute', width, opacity: 0 }]}
        >
          {text}
        </Text>
      )}

      <View style={{ flexDirection: 'row', alignItems: 'flex-end' }}>
        <Text
          style={[textStyle, { flex: 1 }]}
          numberOfLines={isOverflowing && !expanded ? 1 : undefined}
        >
          {text}
        </Text>

        {isOverflowing && !expanded && (
          <Pressable
            onPress={() => setExpanded(true)}
            accessibilityRole="button"
            accessibilityLabel={seeMoreLabel}
          >
            <Text style={seeMoreStyle}>{seeMoreLabel}</Text>
          </Pressable>
        )}
      </View>
    </View>
  );
}
```

Usage:

```jsx
<ExpandableText
  text={text}
  containerStyle={{ width: '100%' }}
  textStyle={{ fontSize: 16, color: '#333' }}
  seeMoreStyle={{ color: '#007AFF', marginLeft: 6 }}
/>
```

The control is adjacent to the text rather than guaranteed to be part of the same line; precise inline placement requires additional width-aware truncation logic.

